import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputPassword, setInputPassword] = useState('');

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    setShowLoginModal(false);
    try {
      const response = await fetch('http://localhost:5000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: inputName, password: inputPassword })
      });
      const data = await response.json();
      if (data.status === 'Success') {
        setStudentName(inputName);
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Error: Server connection failed!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setStudentName('');
    setInputName('');
    setInputPassword('');
    setCurrentPage('Home');
  };

 return (
  <div style={{ position: 'relative', minHeight: '100vh' }}>
    
    <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 50px', background: '#fff' }}>
      <div style={{ fontWeight: 'bold', fontSize: '24px' }}>AuraPEN</div>
      <div style={{ display: 'flex', gap: '20px', cursor: 'pointer' }}>
        <span onClick={() => setCurrentPage('Home')}>Home</span>
        <span onClick={() => setCurrentPage('Classes')}>Classes</span>
        <span onClick={() => setShowLoginModal(true)}>Login</span>
      </div>
    </nav>

    <main>
      {currentPage === 'Home' && <Home />}
      {currentPage === 'Classes' && <Timetable />}
    </main>

    {showLoginModal && (
      <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 9999 }}>
        <div style={{ width: '800px', height: '400px', background: '#fff', borderRadius: '20px', position: 'relative', padding: '40px' }}>
          <div onClick={() => setShowLoginModal(false)} style={{ position: 'absolute', top: '10px', left: '10px', cursor: 'pointer', fontSize: '24px' }}>←</div>
          <h2>Login</h2>
          <form onSubmit={handleLoginSubmit}>
            <input type="text" placeholder="Username" onChange={(e) => setInputName(e.target.value)} style={{ display: 'block', marginBottom: '10px', padding: '10px', width: '100%' }} />
            <input type="password" placeholder="Password" onChange={(e) => setInputPassword(e.target.value)} style={{ display: 'block', marginBottom: '10px', padding: '10px', width: '100%' }} />
            <button type="submit">Login</button>
          </form>
        </div>
      </div>
    )}
  </div>
);
}
